#!/bin/sh
set -eu
# Passwords generated by setup-storage are hexadecimal.
app_pass=$(cat /run/db-init/db-password)
psql --username postgres --dbname th0ughts -v ON_ERROR_STOP=1 <<SQL
CREATE ROLE th0ughts LOGIN PASSWORD '${app_pass}';
ALTER DATABASE th0ughts OWNER TO th0ughts;
ALTER SCHEMA public OWNER TO th0ughts;
SQL
